const el=id=>document.getElementById(id);
const isPlatformHome=!new URLSearchParams(location.search).has("store")&&(location.pathname==="/"||location.pathname.endsWith("/index.html"));

function applyTheme(mode){
 const selected=mode||"system";document.documentElement.dataset.theme=selected;
 const icon=el("themeToggleIcon"),label=el("themeToggleLabel"),button=el("themeToggle");
 if(icon)icon.textContent=selected==="dark"?"☾":selected==="light"?"☀":"◐";
 const t=translations[language]||translations.ar;
 if(label)label.textContent=(selected==="dark"?t.themeDark:selected==="light"?t.themeLight:t.themeSystem);
 if(button){button.title=t.themeCurrent+": "+(label?.textContent||t.themeSystem)+" — "+t.themeChange;button.setAttribute("aria-label",button.title);}
}
function initTheme(){
 let mode="system";try{mode=localStorage.getItem("msdz-theme-shopper")||"system";}catch(error){}
 applyTheme(mode);
 const button=el("themeToggle");if(button)button.addEventListener("click",()=>{
  const current=document.documentElement.dataset.theme||"system",next=current==="system"?"light":current==="light"?"dark":"system";
  try{localStorage.setItem("msdz-theme-shopper",next);}catch(error){}
  applyTheme(next);
 });
}

const safe=value=>String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function productText(p,field){if(field==="name")return (language==="fr"?p.fr:language==="en"?p.en:language==="es"?p.es:language==="de"?p.de:language==="tr"?p.tr:p.name)||p.name;if(language==="fr")return p[field+"Fr"]||p[field];if(language==="en")return p[field+"En"]||p[field];if(language==="es")return p[field+"Es"]||p[field];if(language==="de")return p[field+"De"]||p[field];if(language==="tr")return p[field+"Tr"]||p[field];return p[field];}
function categoryOf(p){return (language==="fr"?p.categoryFr:language==="en"?p.categoryEn:language==="es"?p.categoryEs:language==="de"?p.categoryDe:language==="tr"?p.categoryTr:p.category)||p.category||"General";}
function whatsappLink(p){return "https://wa.me/"+(STORE_SETTINGS.whatsapp||"")+"?text="+encodeURIComponent(translations[language].orderMessage+productText(p,"name"));}
