function renderFilters(){
 const custom=[...new Set(products.map(p=>String(p.category||"").trim()).filter(Boolean))].filter(category=>!standardCategories.some(item=>item.value===category));
 const options=[{value:"all",label:translations[language].all},...standardCategories.map(item=>({value:item.value,label:item[language]})),...custom.map(category=>({value:category,label:category}))];
 el("categorySelect").innerHTML=options.map(x=>'<option value="'+safe(x.value)+'">'+safe(x.label)+'</option>').join("");
 el("categorySelect").value=options.some(x=>x.value===activeCategory)?activeCategory:"all";
 if(el("categorySelect").value!==activeCategory)activeCategory="all";
}
function normalizeSearchText(value){return String(value??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLocaleLowerCase();}
function renderProducts(){
 const term=normalizeSearchText(searchTerm);
 const list=products.filter(p=>{const cat=categoryOf(p),hay=normalizeSearchText([p.name,p.fr,p.en,p.description,p.descriptionFr,p.descriptionEn,p.category,p.categoryFr,p.categoryEn].join(" "));return(activeCategory==="all"||p.category===activeCategory||cat===activeCategory)&&hay.includes(term);});
 el("clearSearch").hidden=!searchTerm.trim();
 el("productGrid").innerHTML=list.map(p=>{const name=productText(p,"name"),desc=productText(p,"description");const visual=p.image_url?'<img src="'+safe(p.image_url)+'" alt="'+safe(name)+'" loading="lazy">':safe(p.emoji||"📦");const tracked=p.stock_quantity!==null&&p.stock_quantity!==undefined,stock=tracked?Number(p.stock_quantity):null,soldOut=tracked&&stock<=0;const stockText=soldOut?translations[language].outOfStock:tracked&&stock<=5?translations[language].lowStock:translations[language].inStock;return '<article class="product-card"><button type="button" class="product-image product-image-button" data-product-details="'+safe(p.id)+'" aria-label="'+safe(translations[language].viewDetails+" "+name)+'">'+visual+'</button><div class="product-info"><span class="product-category">'+safe(categoryOf(p))+'</span><h3>'+safe(name)+'</h3><div class="product-bottom"><span class="price">'+Number(p.price||0).toLocaleString(language==="ar"?"ar-DZ":language==="fr"?"fr-FR":language==="es"?"es-ES":language==="de"?"de-DE":language==="tr"?"tr-TR":"en-US")+' '+translations[language].currency+'</span><button type="button" class="details-text-btn" data-product-details="'+safe(p.id)+'">'+translations[language].viewDetails+'</button></div></div></article>';}).join("");
 el("emptyState").hidden=list.length>0;el("productCount").textContent=list.length+" "+translations[language].count;
}
function renderSellerProfile(){if(!el("sellerName"))return;const name=STORE_SETTINGS.sellerName||"Store Owner";el("sellerName").textContent=name;el("sellerDescription").textContent=STORE_SETTINGS.sellerDescription||translations[language].sellerDescription;el("sellerInitials").textContent=name.trim().charAt(0).toUpperCase()||"S";const avatar=el("sellerAvatar");if(STORE_SETTINGS.sellerAvatar){avatar.src=STORE_SETTINGS.sellerAvatar;avatar.hidden=false;el("sellerInitials").hidden=true;avatar.onerror=()=>{avatar.hidden=true;el("sellerInitials").hidden=false;};}else{avatar.hidden=true;el("sellerInitials").hidden=false;}}

let featuredStores=[];
function renderFeaturedStores(){
 const grid=el("featuredStoresGrid");if(!grid)return;
 if(!featuredStores.length){grid.innerHTML='<p class="featured-empty">'+translations[language].featuredEmpty+'</p>';return;}
 grid.innerHTML=featuredStores.map(store=>'<a class="featured-store-card" href="store.html?store='+encodeURIComponent(store.slug)+'">'+(store.avatar_url?'<img src="'+safe(store.avatar_url)+'" alt="" loading="lazy">':'<span class="featured-store-icon">🏪</span>')+'<span class="featured-store-info"><b>'+safe(store.store_name||store.seller_name||"Mini Store")+'</b><small>'+safe(store.seller_name||"")+'</small><em>'+translations[language].featuredOpen+' ↗</em></span></a>').join("");
}
async function loadFeaturedStores(){
 if(!el("featuredStoresGrid"))return;
 try{
  const {data,error}=await supabase.from("stores").select("store_name,seller_name,avatar_url,slug").eq("is_published",true).limit(6);
  if(error)throw error;featuredStores=data||[];
 }catch(error){console.error("Featured stores:",error);featuredStores=[];}
 renderFeaturedStores();
}
function initHeroShowcase(){
 const root=el("heroShowcase");if(!root)return;
 const slides=[...root.querySelectorAll(".showcase-slide")],dots=[...(el("showcaseDots")?.querySelectorAll("button")||[])];if(slides.length<2)return;
 let current=0;
 const show=index=>{current=(index+slides.length)%slides.length;slides.forEach((slide,i)=>slide.classList.toggle("active",i===current));dots.forEach((dot,i)=>dot.classList.toggle("active",i===current));};
 dots.forEach((dot,i)=>dot.addEventListener("click",()=>show(i)));
 let timer=setInterval(()=>show(current+1),4200);
 root.addEventListener("mouseenter",()=>clearInterval(timer));
 root.addEventListener("mouseleave",()=>{clearInterval(timer);timer=setInterval(()=>show(current+1),4200);});
}

function updateStoreShareLinks(){
 const whatsappShare=el("whatsappStoreShare"),facebookShare=el("facebookStoreShare");
 if(!whatsappShare||!facebookShare)return;
 const url=location.href,encodedUrl=encodeURIComponent(url);
 whatsappShare.href="https://wa.me/?text="+encodeURIComponent(translations[language].shareStore+" — "+url);
 facebookShare.href="https://www.facebook.com/sharer/sharer.php?u="+encodedUrl;
}
async function copyStoreLink(){
 const feedback=el("shareFeedback");
 try{
  if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(location.href);}
  else{
   const field=document.createElement("textarea");field.value=location.href;field.setAttribute("readonly","");field.style.position="fixed";field.style.opacity="0";document.body.appendChild(field);field.select();
   const copied=document.execCommand("copy");field.remove();if(!copied)throw new Error("Clipboard unavailable");
  }
  feedback.textContent=translations[language].shareCopied;
 }catch(error){console.error("Store link copy failed:",error);feedback.textContent=translations[language].shareCopyFailed;}
}
function applyLanguage(){const languagePicker=el("languageSelect");if(languagePicker)languagePicker.value=language;document.documentElement.lang=language;document.documentElement.dir=language==="ar"?"rtl":"ltr";if(!new URLSearchParams(location.search).has("store"))STORE_SETTINGS.sellerDescription=translations[language].sellerDescription;const metaDescription=document.querySelector('meta[name="description"]');if(metaDescription)metaDescription.content=currentStoreId?[STORE_SETTINGS.sellerDescription,translations[language].storeMetaDesc].filter(Boolean).join(" — "):translations[language].metaDescription;const ogDescription=document.querySelector('meta[property="og:description"]');if(ogDescription)ogDescription.content=metaDescription?.content||translations[language].metaDescription;document.querySelectorAll("[data-i18n]").forEach(n=>{const k=n.dataset.i18n;if(translations[language][k])n.innerHTML=translations[language][k];});document.querySelectorAll("[data-i18n-placeholder]").forEach(n=>n.placeholder=translations[language][n.dataset.i18nPlaceholder]);document.querySelectorAll("[data-i18n-aria-label]").forEach(n=>n.setAttribute("aria-label",translations[language][n.dataset.i18nAriaLabel]||n.getAttribute("aria-label")));document.querySelectorAll("[data-i18n-alt]").forEach(n=>n.alt=translations[language][n.dataset.i18nAlt]||n.alt);applyTheme(document.documentElement.dataset.theme||"system");const browseLink=el("browseButton");if(browseLink){browseLink.href=isPlatformHome?"#featuredStoresSection":"#products";if(isPlatformHome)browseLink.textContent=translations[language].browseStores;}const productsNav=el("navProducts");if(productsNav&&isPlatformHome){productsNav.href="#featuredStoresSection";productsNav.textContent=translations[language].navStores;}renderSellerProfile();renderFilters();renderProducts();renderCart();renderFeaturedStores();if(currentStoreId&&el("reviews"))renderPublicReviews();el("contactButton").href="mailto:support.ministoredz@gmail.com?subject="+encodeURIComponent(translations[language].supportSubject);if(el("supportEmailLink"))el("supportEmailLink").href="mailto:support.ministoredz@gmail.com";updateStoreShareLinks();}

function renderDetailGallery(name){
 const t=translations[language],multiple=detailImages.length>1,current=detailImages[detailImageIndex];
 const main=current?'<img src="'+safe(current)+'" alt="'+safe(name)+'">':'<div class="details-placeholder">📦</div>';
 const thumbs=multiple?'<div class="product-gallery-thumbs">'+detailImages.map((url,i)=>'<button type="button" class="product-gallery-thumb '+(i===detailImageIndex?'active':'')+'" data-detail-index="'+i+'"><img src="'+safe(url)+'" alt=""></button>').join("")+'</div>':'';
 const controls=multiple?'<button type="button" class="product-gallery-arrow prev" data-detail-step="-1" aria-label="'+translations[language].prevImage+'">‹</button><span class="product-gallery-count">'+(detailImageIndex+1)+' / '+detailImages.length+'</span><button type="button" class="product-gallery-arrow next" data-detail-step="1" aria-label="'+translations[language].nextImage+'">›</button>':'';
 return '<div class="product-details-image">'+main+controls+'</div>'+thumbs;
}
function openProductDetails(productId){
 const p=products.find(item=>String(item.id)===String(productId));if(!p)return;
 const t=translations[language],name=productText(p,"name"),desc=productText(p,"description")||"";
 const tracked=p.stock_quantity!==null&&p.stock_quantity!==undefined,stock=tracked?Number(p.stock_quantity):null;
 const status=tracked?(stock<=0?t.outOfStock:stock<=5?t.lowStock:t.inStock):t.unlimitedStock;
 detailImages=Array.isArray(p.image_urls)&&p.image_urls.length?p.image_urls.filter(Boolean):(p.image_url?[p.image_url]:[]);
 detailImageIndex=0;
 el("productDetailsContent").innerHTML=renderDetailGallery(name)+'<div class="product-details-copy"><span class="product-category">'+safe(categoryOf(p))+'</span><h2>'+safe(name)+'</h2><p>'+safe(desc)+'</p><div class="product-details-price">'+Number(p.price||0).toLocaleString(language==="ar"?"ar-DZ":language==="fr"?"fr-FR":language==="es"?"es-ES":language==="de"?"de-DE":language==="tr"?"tr-TR":"en-US")+' '+t.currency+'</div><span class="product-stock '+(tracked&&stock<=0?'out-of-stock':tracked&&stock<=5?'low-stock':'')+'">'+safe(status)+'</span><button type="button" class="primary-btn product-details-action" id="productDetailsAction" '+(currentStoreId&&tracked&&stock<=0?'disabled':'')+'>'+(currentStoreId?t.addToCart:t.order)+'</button></div>';
 el("productDetailsDialog").showModal();
 el("productDetailsAction").addEventListener("click",()=>{el("productDetailsDialog").close();if(currentStoreId)addToCart(p.id);else window.open(whatsappLink(p),"_blank","noopener");},{once:true});
}

function cartQuantity(){return cartItems.reduce((sum,item)=>sum+item.quantity,0);}
function cartTotal(){return cartItems.reduce((sum,item)=>sum+Number(item.product.price||0)*item.quantity,0);}
function updateCartButton(){
 const button=el("viewCartButton");if(!button)return;
 button.hidden=!currentStoreId;
 button.textContent=translations[language].viewCart+" ("+cartQuantity()+")";
}
function addToCart(productId){
 const product=products.find(p=>String(p.id)===String(productId));if(!product)return;
 const existing=cartItems.find(item=>String(item.product.id)===String(product.id));
 const limit=product.stock_quantity===null||product.stock_quantity===undefined?99:Number(product.stock_quantity);if(limit<=0)return;if(existing){if(existing.quantity<Math.min(99,limit))existing.quantity++;}else cartItems.push({product,quantity:1});
 updateCartButton();renderCart();
 const feedback=el("cartFeedback");if(feedback)feedback.textContent=translations[language].cartAdded;
}
function changeCartQuantity(productId,delta){
 const item=cartItems.find(entry=>String(entry.product.id)===String(productId));if(!item)return;
 const limit=item.product.stock_quantity===null||item.product.stock_quantity===undefined?99:Number(item.product.stock_quantity);item.quantity=Math.max(1,Math.min(99,limit,item.quantity+delta));renderCart();updateCartButton();
}
function removeCartItem(productId){
 cartItems=cartItems.filter(item=>String(item.product.id)!==String(productId));renderCart();updateCartButton();
}
function renderCart(){
 const list=el("cartItemsList");if(!list)return;
 if(!cartItems.length){list.innerHTML='<p class="cart-empty">'+translations[language].cartEmpty+'</p>';}
 else list.innerHTML=cartItems.map(({product,quantity})=>'<article class="cart-item"><div class="cart-item-info"><strong>'+safe(productText(product,"name"))+'</strong><small>'+Number(product.price||0).toLocaleString(language==="ar"?"ar-DZ":language==="fr"?"fr-FR":language==="es"?"es-ES":language==="de"?"de-DE":language==="tr"?"tr-TR":"en-US")+' '+translations[language].currency+'</small></div><div class="cart-item-controls"><button type="button" data-cart-minus="'+safe(product.id)+'" aria-label="'+translations[language].decrease+'">−</button><span>'+quantity+'</span><button type="button" data-cart-plus="'+safe(product.id)+'" aria-label="'+translations[language].increase+'">+</button><button type="button" class="cart-remove" data-cart-remove="'+safe(product.id)+'">'+translations[language].remove+'</button></div></article>').join("");
 el("cartDialogTotal").textContent=translations[language].cartTotal+": "+cartTotal().toLocaleString(language==="ar"?"ar-DZ":language==="fr"?"fr-FR":language==="es"?"es-ES":language==="de"?"de-DE":language==="tr"?"tr-TR":"en-US")+" "+translations[language].currency;
 el("checkoutCartButton").disabled=!cartItems.length;updateCartButton();
}
function openCart(){renderCart();el("cartDialog").showModal();}
function openOrderDialog(){
 if(!cartItems.length)return;
 const t=translations[language];
 el("orderDialogTitle").textContent=t.orderFormTitle;
 el("orderProductSummary").textContent=cartItems.map(({product,quantity})=>productText(product,"name")+" × "+quantity).join(language==="ar"?"، ":", ");
 el("orderDialogTotal").textContent=t.cartTotal+": "+cartTotal().toLocaleString(language==="ar"?"ar-DZ":language==="fr"?"fr-FR":language==="es"?"es-ES":language==="de"?"de-DE":language==="tr"?"tr-TR":"en-US")+" "+t.currency;
 el("submitCustomerOrder").textContent=t.sendOrder;el("orderDialogFeedback").textContent="";el("orderDialog").showModal();
}
async function submitCustomerOrder(event){
 event.preventDefault();if(!currentStoreId||!cartItems.length)return;
 const name=el("customerName").value.trim(),phone=el("customerPhone").value.trim(),notes=el("customerNotes").value.trim();
 if(!name||!phone)return;
 const {data:latestProducts,error:stockError}=await supabase.from("products").select("id,stock_quantity,is_active").in("id",cartItems.map(item=>item.product.id));if(stockError){el("orderDialogFeedback").textContent=translations[language].orderFailed;return;}for(const item of cartItems){const latest=latestProducts.find(p=>p.id===item.product.id);if(!latest||!latest.is_active||(latest.stock_quantity!==null&&latest.stock_quantity!==undefined&&Number(latest.stock_quantity)<item.quantity)){el("orderDialogFeedback").textContent=translations[language].stockChanged;return;}}const popup=window.open("about:blank","_blank");
 const items=cartItems.map(({product,quantity})=>({product_id:product.id,name:productText(product,"name"),quantity,unit_price:Number(product.price||0)}));
 const total=cartTotal();
 el("submitCustomerOrder").disabled=true;el("orderDialogFeedback").textContent=translations[language].orderSaving;
 try{
  const {error}=await supabase.from("orders").insert({store_id:currentStoreId,customer_name:name,customer_phone:phone,items,total,notes:notes||null});if(error)throw error;
  const details=items.map((item,index)=>(index+1)+". "+item.name+" × "+item.quantity+" = "+(item.unit_price*item.quantity).toLocaleString()+" DZD").join("\n");
  const msg=translations[language].whatsAppGreeting+"\n"+details+"\n"+translations[language].totalLabel+": "+total.toLocaleString()+" DZD\n"+translations[language].customerName+": "+name+"\n"+translations[language].customerPhone+": "+phone+(notes?"\n"+translations[language].orderNotes+": "+notes:"");
  const target="https://wa.me/"+(STORE_SETTINGS.whatsapp||"")+"?text="+encodeURIComponent(msg);if(popup)popup.location=target;else window.location.href=target;
  cartItems=[];renderCart();el("customerOrderForm").reset();el("orderDialogFeedback").textContent=translations[language].orderSaved;setTimeout(()=>el("orderDialog").close(),900);
 }catch(error){if(popup)popup.close();console.error(error);el("orderDialogFeedback").textContent=translations[language].orderFailed;}finally{el("submitCustomerOrder").disabled=false;}
}


async function loadPublicReviews(){
 const section=el("reviews");if(!section||!currentStoreId)return;
 section.hidden=false;
 const pageSize=1000;let allReviews=[],from=0;
 while(true){
  const {data,error}=await supabase.from("store_reviews").select("id,customer_name,rating,comment,created_at").eq("store_id",currentStoreId).eq("status","approved").order("created_at",{ascending:false}).range(from,from+pageSize-1);
  if(error){console.error("Reviews loading error:",error);return;}
  const batch=data||[];allReviews=allReviews.concat(batch);if(batch.length<pageSize)break;from+=pageSize;
 }
 publicReviewStats=allReviews;publicReviews=allReviews.slice(0,20);renderPublicReviews();
}
function renderPublicReviews(){
 const count=publicReviewStats.length,average=count?publicReviewStats.reduce((sum,r)=>sum+Number(r.rating),0)/count:0;
 el("reviewsAverage").textContent=count?average.toFixed(1)+"/5":"—";
 el("reviewsStars").textContent=count?"★".repeat(Math.round(average))+"☆".repeat(5-Math.round(average)):"☆☆☆☆☆";
 el("reviewsCount").textContent=count+" "+translations[language].reviewCount;
 const distribution=[5,4,3,2,1].map(star=>{const total=publicReviewStats.filter(r=>Number(r.rating)===star).length;const percent=count?total/count*100:0;return '<div class="rating-row"><span class="rating-label">'+star+' ★</span><div class="rating-track"><span style="width:'+percent.toFixed(2)+'%"></span></div><small>'+total+'</small></div>';}).join("");
 el("reviewsBreakdown").innerHTML=distribution;
 el("publicReviews").innerHTML=count?publicReviews.map(r=>'<article class="public-review"><div class="public-review-top"><strong>'+safe(r.customer_name)+'</strong><span class="review-stars">'+("★".repeat(Number(r.rating))+"☆".repeat(5-Number(r.rating)))+'</span></div><p>'+safe(r.comment)+'</p><small>'+new Date(r.created_at).toLocaleDateString(language==="ar"?"ar-DZ":language==="fr"?"fr-FR":"en-US")+'</small></article>').join(""):'<p class="empty-state">'+translations[language].noReviews+'</p>';
}
async function submitCustomerReview(event){
 event.preventDefault();if(!currentStoreId)return;
 const name=el("reviewCustomerName").value.trim(),rating=Number(el("reviewRating").value),comment=el("reviewComment").value.trim();
 if(name.length<2||comment.length<3||!Number.isInteger(rating)||rating<1||rating>5)return;
 const button=el("submitReview");button.disabled=true;el("reviewFeedback").textContent="";
 try{
  const {error}=await supabase.from("store_reviews").insert({store_id:currentStoreId,customer_name:name,rating,comment});
  if(error)throw error;
  el("customerReviewForm").reset();el("reviewFeedback").textContent=translations[language].reviewPending;
 }catch(error){console.error("Review submission error:",error);el("reviewFeedback").textContent=translations[language].reviewFailed;}
 finally{button.disabled=false;}
}

async function loadStore(){
 const slug=new URLSearchParams(location.search).get("store");if(!slug)return;
 try{
  const {data:store,error}=await supabase.from("stores").select("id,store_name,seller_name,seller_bio,avatar_url,whatsapp,description,slug").eq("slug",slug).eq("is_published",true).maybeSingle();
  if(error)throw error;if(!store){products=[];STORE_SETTINGS={...DEFAULT_STORE_SETTINGS,sellerName:translations[language].storeUnavailable,sellerDescription:translations[language].storeUnavailableDesc,whatsapp:""};const meta=document.querySelector('meta[name="description"]');if(meta)meta.content=translations[language].storeUnavailableDesc;document.title=translations[language].storeUnavailable+" | Mini Store DZ";return;}
  currentStoreId=store.id;STORE_SETTINGS={whatsapp:store.whatsapp||"",sellerName:store.seller_name||store.store_name,sellerDescription:[store.store_name,store.seller_bio].filter(Boolean).join(" · "),sellerAvatar:store.avatar_url||""};
  const {data:list,error:productError}=await supabase.from("products").select("id,name,description,category,price,currency,image_url,image_urls,stock_quantity").eq("store_id",store.id).eq("is_active",true).order("created_at",{ascending:false});
  if(productError)throw productError;products=(list||[]).map(p=>({...p,emoji:"📦"}));
  document.title=store.store_name+" | Mini Store DZ";
  const pageDescription=[store.store_name,store.seller_bio,translations[language].storeMetaDesc].filter(Boolean).join(" — ");
  const descriptionMeta=document.querySelector('meta[name="description"]');if(descriptionMeta)descriptionMeta.content=pageDescription;
  const ogTitle=document.querySelector('meta[property="og:title"]');if(ogTitle)ogTitle.content=store.store_name+" | Mini Store DZ";
  const ogDescription=document.querySelector('meta[property="og:description"]');if(ogDescription)ogDescription.content=pageDescription;
 }catch(error){console.error("Store loading error:",error);}
}
